+		headers['Content-Length'] = `${typeof options.contentLength === 'number'
+			? options.contentLength
+			: data.size || data.length || data.byteLength}`
+	}
+
+	if (options.overwrite === false) {
+		headers['If-None-Match'] = '*'
+	}
+
+	return axios({
+		url: remote + encodePath(filePath),
+		method: 'PUT',
+		headers,
+		data,
+		onUploadProgress: options.onUploadProgress,
+		signal: options.signal,
+		validateStatus: status => status < 400 || (status === 412 && options.overwrite === false),
